namespace TUnit.Mutation.Driver.Runtime;

/// Source written into the test project directory (as a .g.cs file) so TUnit's source generator
/// picks up the [BeforeEvery(Test)] / [AfterEvery(Test)] hooks during normal build.
///
/// Uses the post-rewrite TUnit public API: context.ClassContext.ClassType + context.Metadata.TestName.
/// TestDetails is internal as of TUnit's "A bit of a rewrite" change (PR #2600).
public static class CoverageHooksSource
{
    public const string FileName = "__TUnitMutation.CoverageHooks.g.cs";

    public const string Code = """
        // <auto-generated />
        #nullable enable
        namespace TUnit.Mutation.Generated
        {
            using TUnit.Core;
            using static TUnit.Core.HookType;

            public static class MutationCoverageHooks
            {
                [BeforeEvery(Test)]
                public static void BeforeTest(TestContext context)
                {
                    var path = System.Environment.GetEnvironmentVariable("MUTATION_ACTIVE_FILE");
                    if (!string.IsNullOrEmpty(path) && System.IO.File.Exists(path))
                    {
                        var csv = System.IO.File.ReadAllText(path).Trim();
                        global::TUnit.Mutation.Generated.MutationRuntime.SetActive(csv);
                    }
                    global::TUnit.Mutation.Generated.MutationRuntime.BeginTest();
                }

                [AfterEvery(Test)]
                public static void AfterTest(TestContext context)
                {
                    var classType = context.ClassContext.ClassType;
                    var asm = classType.Assembly.GetName().Name;
                    var ns = classType.Namespace;
                    var cls = classType.Name;
                    var method = context.Metadata.TestName;
                    // TreeNodeFilter path format used by TUnit's filter matcher.
                    // The orchestrator passes these verbatim via --treenode-filter.
                    var path = "/" + asm + "/" + ns + "/" + cls + "/" + method;
                    var id = (classType.FullName ?? (ns + "." + cls)) + "." + method;
                    global::TUnit.Mutation.Generated.MutationRuntime.EndTest(id, path);
                }
            }
        }
        """;
}
